using AlSsareea.Api.Security;
using AlSsareea.Modules.Catalog.Application;
using AlSsareea.Modules.Catalog.Contracts;
using AlSsareea.Modules.Identity.Application;
using Microsoft.AspNetCore.Mvc;

namespace AlSsareea.Api.Endpoints;

public static class CatalogEndpoints
{
    public static IEndpointRouteBuilder MapCatalogEndpoints(this IEndpointRouteBuilder app)
    {
        RouteGroupBuilder root = app.MapGroup("/api/v1/merchants/{merchantId:guid}/catalog").WithTags("Catalog");
        root.MapGet("", GetPublic); root.MapGet("/categories", ListPublicCategories); root.MapGet("/sections", ListPublicSections); root.MapGet("/products", SearchPublic); root.MapGet("/search", SearchPublic); root.MapGet("/products/{productId:guid}", GetPublicProduct).Produces<CustomerProductDetailsResponse>().ProducesProblem(404); root.MapPost("/products/{productId:guid}/price", Price);
        RouteGroupBuilder management = root.MapGroup("").RequireAuthorization();
        management.MapPost("", Create).RequireAuthorization(Permission(CatalogPermissions.Manage)); management.MapPut("", Update).RequireAuthorization(Permission(CatalogPermissions.Manage));
        foreach (string operation in new[] { "activate", "suspend", "archive" }) management.MapPost("/" + operation, (Guid merchantId, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => ChangeCatalog(merchantId, operation, r, c, s, ct)).RequireAuthorization(Permission(CatalogPermissions.Manage));
        management.MapPost("/categories", CreateCategory).RequireAuthorization(Permission(CatalogPermissions.CategoriesManage));
        management.MapPut("/categories/{categoryId:guid}", UpdateCategory).RequireAuthorization(Permission(CatalogPermissions.CategoriesManage));
        management.MapPut("/categories/{categoryId:guid}/image", SetCategoryImage).RequireAuthorization(Permission(CatalogPermissions.ImagesManage));
        management.MapPost("/categories/{categoryId:guid}/show", (Guid merchantId, Guid categoryId, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => CategoryVisibility(merchantId, categoryId, true, r, c, s, ct)).RequireAuthorization(Permission(CatalogPermissions.CategoriesManage));
        management.MapPost("/categories/{categoryId:guid}/hide", (Guid merchantId, Guid categoryId, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => CategoryVisibility(merchantId, categoryId, false, r, c, s, ct)).RequireAuthorization(Permission(CatalogPermissions.CategoriesManage));
        management.MapPut("/categories/reorder", ReorderCategories).RequireAuthorization(Permission(CatalogPermissions.CategoriesManage));
        management.MapPost("/sections", CreateSection).RequireAuthorization(Permission(CatalogPermissions.SectionsManage));
        management.MapPut("/sections/{sectionId:guid}", UpdateSection).RequireAuthorization(Permission(CatalogPermissions.SectionsManage));
        management.MapPost("/sections/{sectionId:guid}/show", (Guid merchantId, Guid sectionId, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => SectionVisibility(merchantId, sectionId, true, r, c, s, ct)).RequireAuthorization(Permission(CatalogPermissions.SectionsManage));
        management.MapPost("/sections/{sectionId:guid}/hide", (Guid merchantId, Guid sectionId, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => SectionVisibility(merchantId, sectionId, false, r, c, s, ct)).RequireAuthorization(Permission(CatalogPermissions.SectionsManage));
        management.MapPut("/sections/reorder", ReorderSections).RequireAuthorization(Permission(CatalogPermissions.SectionsManage));
        management.MapPost("/sections/{sectionId:guid}/products", AddSectionProduct).RequireAuthorization(Permission(CatalogPermissions.SectionsManage));
        management.MapDelete("/sections/{sectionId:guid}/products/{productId:guid}", RemoveSectionProduct).RequireAuthorization(Permission(CatalogPermissions.SectionsManage));
        management.MapPut("/sections/{sectionId:guid}/products/reorder", ReorderSectionProducts).RequireAuthorization(Permission(CatalogPermissions.SectionsManage));
        management.MapGet("/manage/products", SearchAdmin).RequireAuthorization(Permission(CatalogPermissions.ProductsView)); management.MapPost("/products", CreateProduct).RequireAuthorization(Permission(CatalogPermissions.ProductsCreate)); management.MapPut("/products/{productId:guid}", UpdateProduct).RequireAuthorization(Permission(CatalogPermissions.ProductsUpdate));
        management.MapPost("/products/{productId:guid}/publish", (Guid merchantId, Guid productId, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => ChangeProduct(merchantId, productId, "publish", r.ConcurrencyStamp, null, c, s, ct)).RequireAuthorization(Permission(CatalogPermissions.ProductsPublish));
        foreach (string operation in new[] { "suspend", "archive", "show", "hide" }) management.MapPost($"/products/{{productId:guid}}/{operation}", (Guid merchantId, Guid productId, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => ChangeProduct(merchantId, productId, operation, r.ConcurrencyStamp, null, c, s, ct)).RequireAuthorization(Permission(CatalogPermissions.ProductsLifecycle));
        management.MapPut("/products/{productId:guid}/inventory-status", (Guid merchantId, Guid productId, InventoryStatusRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => ChangeProduct(merchantId, productId, "inventory", r.ConcurrencyStamp, r.InventoryStatus, c, s, ct)).RequireAuthorization(Permission(CatalogPermissions.InventoryManage));
        management.MapPut("/products/{productId:guid}/translations", SetProductTranslation).RequireAuthorization(Permission(CatalogPermissions.LocalizationManage));
        management.MapPut("/products/{productId:guid}/availability", SetAvailability).RequireAuthorization(Permission(CatalogPermissions.AvailabilityManage));
        management.MapPost("/products/{productId:guid}/variants", AddVariant).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPut("/products/{productId:guid}/variants/{variantId:guid}", UpdateVariant).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPut("/products/{productId:guid}/variants/reorder", ReorderVariants).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPost("/products/{productId:guid}/variants/{variantId:guid}/set-default", SetDefaultVariant).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPost("/products/{productId:guid}/option-groups", AddOptionGroup).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPut("/products/{productId:guid}/option-groups/{groupId:guid}", UpdateOptionGroup).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPut("/products/{productId:guid}/option-groups/reorder", ReorderOptionGroups).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPost("/products/{productId:guid}/option-groups/{groupId:guid}/options", AddOption).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPut("/products/{productId:guid}/option-groups/{groupId:guid}/options/{optionId:guid}", UpdateOption).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPut("/products/{productId:guid}/option-groups/{groupId:guid}/options/reorder", ReorderOptions).RequireAuthorization(Permission(CatalogPermissions.OptionsManage));
        management.MapPost("/products/{productId:guid}/images", AddImage).RequireAuthorization(Permission(CatalogPermissions.ImagesManage));
        management.MapPut("/products/{productId:guid}/images/{imageId:guid}", UpdateImage).RequireAuthorization(Permission(CatalogPermissions.ImagesManage));
        management.MapPost("/products/{productId:guid}/images/{imageId:guid}/set-primary", SetPrimaryImage).RequireAuthorization(Permission(CatalogPermissions.ImagesManage));
        management.MapDelete("/products/{productId:guid}/images/{imageId:guid}", RemoveImage).RequireAuthorization(Permission(CatalogPermissions.ImagesManage));
        management.MapPut("/products/{productId:guid}/images/reorder", ReorderImages).RequireAuthorization(Permission(CatalogPermissions.ImagesManage));
        return app;
    }
    private static Task<IResult> Create([FromRoute] Guid merchantId, [FromBody] CreateCatalogRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.CreateCatalogAsync(merchantId, r, Actor(c), ct));
    private static Task<IResult> GetPublic([FromRoute] Guid merchantId, [FromQuery] string? language, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.GetCatalogAsync(merchantId, true, language, Anonymous, ct));
    private static Task<IResult> ListPublicCategories([FromRoute] Guid merchantId, [FromQuery] string? language, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.ListCategoriesAsync(merchantId, true, language, Anonymous, ct));
    private static Task<IResult> ListPublicSections([FromRoute] Guid merchantId, [FromQuery] string? language, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.ListSectionsAsync(merchantId, true, language, Anonymous, ct));
    private static Task<IResult> Update(Guid merchantId, UpdateCatalogRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => Run(s.UpdateCatalogAsync(merchantId, r, Actor(c), ct));
    private static Task<IResult> ChangeCatalog(Guid merchantId, string operation, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => Run(s.ChangeCatalogStatusAsync(merchantId, operation, r, Actor(c), ct));
    private static Task<IResult> CreateCategory([FromRoute] Guid merchantId, [FromBody] CreateCategoryRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.CreateCategoryAsync(merchantId, r, Actor(c), ct));
    private static Task<IResult> UpdateCategory([FromRoute] Guid merchantId, [FromRoute] Guid categoryId, [FromBody] UpdateCategoryRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.UpdateCategoryAsync(merchantId, categoryId, r, Actor(c), ct));
    private static Task<IResult> SetCategoryImage([FromRoute] Guid merchantId, [FromRoute] Guid categoryId, [FromBody] SetCatalogImageRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.SetCategoryImageAsync(merchantId, categoryId, r, Actor(c), ct));
    private static Task<IResult> CategoryVisibility(Guid merchantId, Guid categoryId, bool visible, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => Run(s.SetCategoryVisibilityAsync(merchantId, categoryId, visible, r, Actor(c), ct));
    private static Task<IResult> ReorderCategories([FromRoute] Guid merchantId, [FromBody] ReorderRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.ReorderCategoriesAsync(merchantId, r, Actor(c), ct));
    private static Task<IResult> CreateSection([FromRoute] Guid merchantId, [FromBody] CreateMenuSectionRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.CreateSectionAsync(merchantId, r, Actor(c), ct));
    private static Task<IResult> UpdateSection([FromRoute] Guid merchantId, [FromRoute] Guid sectionId, [FromBody] UpdateMenuSectionRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.UpdateSectionAsync(merchantId, sectionId, r, Actor(c), ct));
    private static Task<IResult> SectionVisibility(Guid merchantId, Guid sectionId, bool visible, ConcurrencyRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => Run(s.SetSectionVisibilityAsync(merchantId, sectionId, visible, r, Actor(c), ct));
    private static Task<IResult> ReorderSections([FromRoute] Guid merchantId, [FromBody] ReorderRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.ReorderSectionsAsync(merchantId, r, Actor(c), ct));
    private static Task<IResult> AddSectionProduct([FromRoute] Guid merchantId, [FromRoute] Guid sectionId, [FromBody] AddSectionProductRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.AddSectionProductAsync(merchantId, sectionId, r, Actor(c), ct));
    private static Task<IResult> RemoveSectionProduct([FromRoute] Guid merchantId, [FromRoute] Guid sectionId, [FromRoute] Guid productId, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.RemoveSectionProductAsync(merchantId, sectionId, productId, Actor(c), ct));
    private static Task<IResult> ReorderSectionProducts([FromRoute] Guid merchantId, [FromRoute] Guid sectionId, [FromBody] ReorderRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.ReorderSectionProductsAsync(merchantId, sectionId, r, Actor(c), ct));
    private static Task<IResult> CreateProduct(Guid merchantId, CreateProductRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => Run(s.CreateProductAsync(merchantId, r, Actor(c), ct));
    private static Task<IResult> GetPublicProduct(Guid merchantId, Guid productId, [FromQuery] string? language, [FromQuery] Guid? branchId, ICatalogService s, CancellationToken ct) => Run(s.GetProductAsync(merchantId, productId, true, language, branchId, Anonymous, ct));
    private static Task<IResult> UpdateProduct(Guid merchantId, Guid productId, UpdateProductRequest r, ICurrentUser c, ICatalogService s, CancellationToken ct) => Run(s.UpdateProductAsync(merchantId, productId, r, Actor(c), ct));
    private static Task<IResult> SetProductTranslation([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromBody] ProductTranslationRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.SetProductTranslationAsync(merchantId, productId, r, Actor(c), ct));
    private static Task<IResult> SetAvailability([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromBody] SetAvailabilityRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.SetAvailabilityAsync(merchantId, productId, r, Actor(c), ct));
    private static Task<IResult> AddVariant([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromBody] AddVariantRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.AddVariantAsync(merchantId, productId, r, Actor(c), ct));
    private static Task<IResult> UpdateVariant([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromRoute] Guid variantId, [FromBody] UpdateVariantRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.UpdateVariantAsync(merchantId, productId, variantId, r, Actor(c), ct));
    private static Task<IResult> ReorderVariants([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromBody] ReorderRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.ReorderVariantsAsync(merchantId, productId, r, Actor(c), ct));
    private static Task<IResult> SetDefaultVariant([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromRoute] Guid variantId, [FromBody] ConcurrencyRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.SetDefaultVariantAsync(merchantId, productId, variantId, r, Actor(c), ct));
    private static Task<IResult> AddOptionGroup([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromBody] AddOptionGroupRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.AddOptionGroupAsync(merchantId, productId, r, Actor(c), ct));
    private static Task<IResult> UpdateOptionGroup([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromRoute] Guid groupId, [FromBody] UpdateOptionGroupRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.UpdateOptionGroupAsync(merchantId, productId, groupId, r, Actor(c), ct));
    private static Task<IResult> ReorderOptionGroups([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromBody] ReorderRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.ReorderOptionGroupsAsync(merchantId, productId, r, Actor(c), ct));
    private static Task<IResult> AddOption([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromRoute] Guid groupId, [FromBody] AddOptionRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.AddOptionAsync(merchantId, productId, groupId, r, Actor(c), ct));
    private static Task<IResult> UpdateOption([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromRoute] Guid groupId, [FromRoute] Guid optionId, [FromBody] UpdateOptionRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.UpdateOptionAsync(merchantId, productId, groupId, optionId, r, Actor(c), ct));
    private static Task<IResult> ReorderOptions([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromRoute] Guid groupId, [FromBody] ReorderRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.ReorderOptionsAsync(merchantId, productId, groupId, r, Actor(c), ct));
    private static Task<IResult> AddImage([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromBody] AddImageReferenceRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.AddImageAsync(merchantId, productId, r, Actor(c), ct));
    private static Task<IResult> UpdateImage([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromRoute] Guid imageId, [FromBody] UpdateImageReferenceRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.UpdateImageAsync(merchantId, productId, imageId, r, Actor(c), ct));
    private static Task<IResult> SetPrimaryImage([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromRoute] Guid imageId, [FromBody] ConcurrencyRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.SetPrimaryImageAsync(merchantId, productId, imageId, r, Actor(c), ct));
    private static Task<IResult> RemoveImage([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromRoute] Guid imageId, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.RemoveImageAsync(merchantId, productId, imageId, Actor(c), ct));
    private static Task<IResult> ReorderImages([FromRoute] Guid merchantId, [FromRoute] Guid productId, [FromBody] ReorderRequest r, [FromServices] ICurrentUser c, [FromServices] ICatalogService s, CancellationToken ct) => Run(s.ReorderImagesAsync(merchantId, productId, r, Actor(c), ct));
    private static Task<IResult> ChangeProduct(Guid merchantId, Guid productId, string operation, Guid stamp, short? inventory, ICurrentUser c, ICatalogService s, CancellationToken ct) => Run(s.ChangeProductAsync(merchantId, productId, operation, stamp, inventory, Actor(c), ct));
    private static Task<IResult> SearchPublic(Guid merchantId, [FromQuery] int page, [FromQuery] int pageSize, [FromQuery] string? query, [FromQuery] Guid? categoryId, [FromQuery] string? language, ICatalogService s, CancellationToken ct) => Run(s.SearchProductsAsync(merchantId, page == 0 ? 1 : page, pageSize == 0 ? 20 : pageSize, query, categoryId, null, null, null, true, language, Anonymous, ct));
    private static Task<IResult> SearchAdmin(Guid merchantId, [FromQuery] int page, [FromQuery] int pageSize, [FromQuery] string? query, [FromQuery] Guid? categoryId, [FromQuery] short? status, [FromQuery] short? inventoryStatus, [FromQuery] bool? visible, [FromQuery] string? language, ICurrentUser c, ICatalogService s, CancellationToken ct) => Run(s.SearchProductsAsync(merchantId, page == 0 ? 1 : page, pageSize == 0 ? 20 : pageSize, query, categoryId, status, inventoryStatus, visible, false, language, Actor(c), ct));
    private static Task<IResult> Price(Guid merchantId, Guid productId, PriceRequest r, ICatalogService s, CancellationToken ct) => Run(s.CalculatePriceAsync(merchantId, productId, r, ct));
    private static CatalogActor Actor(ICurrentUser c) => new(c.UserId?.Value ?? Guid.Empty, c.Roles.Any(x => x is "admin" or "platform-admin" or "operations")); private static readonly CatalogActor Anonymous = new(Guid.Empty, false); private static string Permission(string x) => AuthenticationPolicies.PermissionPrefix + x;
    private static async Task<IResult> Run<T>(Task<CatalogOperationResult<T>> task) { CatalogOperationResult<T> r = await task; return r.Status switch { CatalogOperationStatus.Success => Results.Ok(r.Value), CatalogOperationStatus.Created => Results.Json(r.Value, statusCode: 201), CatalogOperationStatus.NotFound => Problem(404, r.ErrorCode), CatalogOperationStatus.Forbidden => Problem(403, r.ErrorCode), CatalogOperationStatus.Conflict => Problem(409, r.ErrorCode), _ => Problem(400, r.ErrorCode) }; }
    private static IResult Problem(int status, string? code) => Results.Problem(statusCode: status, title: status switch { 403 => "Forbidden", 404 => "Not found", 409 => "Conflict", _ => "Invalid request" }, extensions: new Dictionary<string, object?> { ["code"] = code });
}
